// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 seed) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        bool reverted;
        uint256 beforeBal = address(c).balance;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal = address(c).balance;
        assertTrue(!reverted || afterBal == beforeBal);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
